private static void drawBeams(double distance, CorruptedBeam entity, float ticks, float speedModifier, PoseStack pMatrixStack) {
        long gameTime = entity.level.getGameTime();
        double velocity = gameTime * speedModifier;
        float additiveThickness = (entity.getBeamWidth() * 1.75f) * calculateLaserFlickerModifier(gameTime);

        float yRot = -Mth.rotLerp(ticks, entity.yRotO, entity.getYRot());
        float xRot = Mth.rotLerp(ticks, entity.xRotO, entity.getXRot());
        Vec3 offset = Vec3.ZERO;
        Optional<LivingEntity> optionalOwner = entity.getOptionalOwner();
        if (optionalOwner.isPresent()) {
            LivingEntity owner = optionalOwner.get();
            yRot = -Mth.rotLerp(ticks, owner.yRotO, owner.getYRot());
            xRot = Mth.rotLerp(ticks, owner.xRotO, owner.getXRot());
            offset = new Vec3(
                    Mth.lerp(ticks, owner.xo, owner.getX()) - Mth.lerp(ticks, entity.xo, entity.getX()),
                    Mth.lerp(ticks, owner.yo, owner.getY()) - Mth.lerp(ticks, entity.yo, entity.getY()),
                    Mth.lerp(ticks, owner.zo, owner.getZ()) - Mth.lerp(ticks, entity.zo, entity.getZ())
            ).add(entity.getOffsetVector(owner, ticks));
        }

        pMatrixStack.pushPose();
        pMatrixStack.translate(offset.x, offset.y, offset.z);
        pMatrixStack.mulPose(Axis.YP.rotationDegrees(yRot));
        pMatrixStack.mulPose(Axis.XP.rotationDegrees(xRot));
        PoseStack.Pose matrixstack$entry = pMatrixStack.last();
        QUEUE.add(new QueuedBeam(new Matrix4f(matrixstack$entry.pose()), new Matrix3f(matrixstack$entry.normal()), distance, entity.getBeamWidth(), additiveThickness, velocity, ticks));
        pMatrixStack.popPose();
    }

public static void renderQueued(MultiBufferSource.BufferSource buffer) {
        if (QUEUE.isEmpty()) {
            return;
        }
        for (QueuedBeam beam : QUEUE) {
            drawClosingBeam(buffer.getBuffer(ModRenderType.magicBeam(beaconBeamGlow)), beam.pose(), beam.normal(), beam.additiveThickness(), beam.distance() / 10, 0.5, 1, beam.ticks(), 0.9f);
        }
        buffer.endBatch(ModRenderType.magicBeam(beaconBeamGlow));
        for (QueuedBeam beam : QUEUE) {
            drawBeam(buffer.getBuffer(ModRenderType.magicBeam(beaconBeamMain)), beam.pose(), beam.normal(), beam.width(), beam.distance(), beam.velocity(), beam.velocity() + beam.distance() * 1.5, beam.ticks(), 0.7f);
        }
        buffer.endBatch(ModRenderType.magicBeam(beaconBeamMain));
        for (QueuedBeam beam : QUEUE) {
            drawBeam(buffer.getBuffer(ModRenderType.magicBeam(beaconBeamCore)), beam.pose(), beam.normal(), beam.width() * 0.7f, beam.distance(), beam.velocity(), beam.velocity() + beam.distance() * 1.5, beam.ticks(), 1f);
        }
        buffer.endBatch(ModRenderType.magicBeam(beaconBeamCore));
        QUEUE.clear();
    }

private void renderTrail(NecroBolt entityIn, float partialTicks, PoseStack matrixStackIn, MultiBufferSource bufferIn, float red, float green, float blue, float alpha, int packedLightIn) {
        int samples = 0;
        int sampleSize = 1;
        double trailHeight = 0.5D;
        float trailZRot = 0;
        Vec3 topAngleVec = new Vec3(0.0D, trailHeight, 0.0D).zRot(trailZRot);
        Vec3 bottomAngleVec = new Vec3(0.0D, -trailHeight, 0.0D).zRot(trailZRot);
        Vec3 drawFrom = entityIn.getTrailPosition(0, partialTicks);
        VertexConsumer vertexconsumer = bufferIn.getBuffer(RenderType.entityTranslucent(TRAIL));
        while (samples < sampleSize) {
            Vec3 sample = entityIn.getTrailPosition(samples + 8, partialTicks);
            Vec3 draw1 = drawFrom;

            PoseStack.Pose posestack$pose = matrixStackIn.last();
            Matrix4f matrix4f = posestack$pose.pose();
            Matrix3f matrix3f = posestack$pose.normal();
            float f2 = entityIn.tickCount % 8 / 8.0F;
            float f3 = f2 + 0.5F;
            vertexconsumer.vertex(matrix4f, (float) draw1.x + (float) bottomAngleVec.x, (float) draw1.y + (float) bottomAngleVec.y, (float) draw1.z + (float) bottomAngleVec.z).color(red, green, blue, alpha).uv(f2, 1.0F).overlayCoords(OverlayTexture.NO_OVERLAY).uv2(packedLightIn).normal(matrix3f, 0.0F, 1.0F, 0.0F).endVertex();
            vertexconsumer.vertex(matrix4f, (float) sample.x + (float) bottomAngleVec.x, (float) sample.y + (float) bottomAngleVec.y, (float) sample.z + (float) bottomAngleVec.z).color(red, green, blue, alpha).uv(f3, 1.0F).overlayCoords(OverlayTexture.NO_OVERLAY).uv2(packedLightIn).normal(matrix3f, 0.0F, 1.0F, 0.0F).endVertex();
            vertexconsumer.vertex(matrix4f, (float) sample.x + (float) topAngleVec.x, (float) sample.y + (float) topAngleVec.y, (float) sample.z + (float) topAngleVec.z).color(red, green, blue, alpha).uv(f3, 0.0F).overlayCoords(OverlayTexture.NO_OVERLAY).uv2(packedLightIn).normal(matrix3f, 0.0F, 1.0F, 0.0F).endVertex();
            vertexconsumer.vertex(matrix4f, (float) draw1.x + (float) topAngleVec.x, (float) draw1.y + (float) topAngleVec.y, (float) draw1.z + (float) topAngleVec.z).color(red, green, blue, alpha).uv(f2, 0.0F).overlayCoords(OverlayTexture.NO_OVERLAY).uv2(packedLightIn).normal(matrix3f, 0.0F, 1.0F, 0.0F).endVertex();
            samples++;
            drawFrom = sample;
        }
    }

public void render(ScytheSlash entity, float yaw, float partialTicks, PoseStack poseStack, MultiBufferSource bufferSource, int light) {
        if (entity.tickCount < 5) {
            return;
        }

        float age = entity.tickCount + partialTicks;
        float yRot = -Mth.rotLerp(partialTicks, entity.yRotO, entity.getYRot()) + 180;
        float xRot = Mth.rotLerp(partialTicks, entity.xRotO, entity.getXRot());

        poseStack.pushPose();
        poseStack.mulPose(Axis.YP.rotationDegrees(yRot));
        poseStack.mulPose(Axis.XP.rotationDegrees(xRot));
        PoseStack.Pose pose = poseStack.last();
        drawSlash(pose, entity, bufferSource, light, 2);
        poseStack.popPose();

        poseStack.pushPose();
        float x = (float) (Mth.lerp(partialTicks, entity.xOld, entity.getX()));
        float y = (float) (Mth.lerp(partialTicks, entity.yOld, entity.getY()));
        float z = (float) (Mth.lerp(partialTicks, entity.zOld, entity.getZ()));
        Matrix4f transform = new Matrix4f();
        transform.rotate(Axis.YP.rotationDegrees(yRot));
        transform.rotate(Axis.XP.rotationDegrees(xRot));
        Vector4f left = transform.transform(new Vector4f(1.0F, Mth.sin(age * 0.4F) * 0.2F, 0.0F, 1.0F));
        Vector4f right = transform.transform(new Vector4f(-1.0F, Mth.cos(age * 0.4F) * 0.2F, 0.0F, 1.0F));
        entity.leftTrail.prepareRender(new Vec3(x, y, z).add(left.x(), left.y(), left.z()), partialTicks);
        entity.rightTrail.prepareRender(new Vec3(x, y, z).add(right.x(), right.y(), right.z()), partialTicks);
        poseStack.translate(-x, -y, -z);
        ColorUtil colorUtil = new ColorUtil(ChatFormatting.AQUA);
        TrailRenderer.render(entity.leftTrail, bufferSource.getBuffer(RenderType.entityCutoutNoCull(TRAIL_TEXTURE)), poseStack, TrailEffect.TrailOffsetFunction.FACE_CAMERA, true, colorUtil.red, colorUtil.green, colorUtil.blue, 1, light);
        TrailRenderer.render(entity.rightTrail, bufferSource.getBuffer(RenderType.entityCutoutNoCull(TRAIL_TEXTURE)), poseStack, TrailEffect.TrailOffsetFunction.FACE_CAMERA, true, colorUtil.red, colorUtil.green, colorUtil.blue, 1, light);
        poseStack.popPose();
    }

public static void render(TrailEffect effect, VertexConsumer consumer, PoseStack stack, TrailEffect.TrailOffsetFunction function, boolean solid, boolean particleFormat, float r, float g, float b, float a, float u0, float u1, float v0, float v1, int light) {
        int size = effect.renderPoints.size();
        if (size < 2) return;

        Camera camera = Minecraft.getInstance().gameRenderer.getMainCamera();
        float halfWidth = effect.getWidth() / 2;

        Vec3[] tangents = new Vec3[size];
        for (int i = 0; i < size; i++) {
            if (i == 0) {
                Vec3 delta = effect.renderPoints.get(1).pos().subtract(effect.renderPoints.get(0).pos());
                tangents[i] = delta.lengthSqr() < 1e-8 ? new Vec3(0, 0, 1) : delta.normalize();
            } else if (i == size - 1) {
                Vec3 delta = effect.renderPoints.get(size - 1).pos().subtract(effect.renderPoints.get(size - 2).pos());
                tangents[i] = delta.lengthSqr() < 1e-8 ? tangents[i - 1] : delta.normalize();
            } else {
                Vec3 prevToNext = effect.renderPoints.get(i + 1).pos().subtract(effect.renderPoints.get(i - 1).pos());
                tangents[i] = prevToNext.lengthSqr() < 1e-8 ? tangents[i - 1] : prevToNext.normalize();
            }
        }

        Vec3[] upperOffsets = new Vec3[size];
        Vec3[] lowerOffsets = new Vec3[size];
        for (int i = 0; i < size; i++) {
            Vec3 tangent = tangents[i];
            if (tangent.lengthSqr() < 0.5) {
                tangent = new Vec3(0, 1, 0);
            }
            Vec3 offsetDir = function.calculateTrailOffset(effect.renderPoints.get(i).pos().subtract(camera.getPosition()), camera.getXRot(), camera.getYRot(), tangent).normalize();
            if (offsetDir.lengthSqr() < 0.5) {
                offsetDir = new Vec3(0, 1, 0);
            }
            upperOffsets[i] = offsetDir.scale(halfWidth);
            lowerOffsets[i] = offsetDir.scale(-halfWidth);
            if (i > 0 && upperOffsets[i].normalize().dot(upperOffsets[i - 1].normalize()) < 0) {
                upperOffsets[i] = upperOffsets[i].reverse();
                lowerOffsets[i] = lowerOffsets[i].reverse();
            }
        }

        PoseStack.Pose pose = stack.last();
        for (int i = 0; i < size - 1; i++) {
            TrailEffect.TrailPoint from = effect.renderPoints.get(i);
            TrailEffect.TrailPoint to = effect.renderPoints.get(i + 1);

            Vec3 fromUpper = from.pos().add(upperOffsets[i]);
            Vec3 toUpper = to.pos().add(upperOffsets[i + 1]);
            Vec3 toLower = to.pos().add(lowerOffsets[i + 1]);
            Vec3 fromLower = from.pos().add(lowerOffsets[i]);

            float fromAlpha = solid ? 1 : Mth.clamp(a * from.progressFactor(), 0, 1);
            float toAlpha = solid ? 1 : Mth.clamp(a * to.progressFactor(), 0, 1);

            vertex(consumer, pose, fromUpper, Mth.lerp(from.progressFactor(), u0, u1), v0, r, g, b, fromAlpha, light, particleFormat);
            vertex(consumer, pose, toUpper, Mth.lerp(to.progressFactor(), u0, u1), v0, r, g, b, toAlpha, light, particleFormat);
            vertex(consumer, pose, toLower, Mth.lerp(to.progressFactor(), u0, u1), v1, r, g, b, toAlpha, light, particleFormat);
            vertex(consumer, pose, fromLower, Mth.lerp(from.progressFactor(), u0, u1), v1, r, g, b, fromAlpha, light, particleFormat);
        }
    }

private void renderShields(PoseStack stack, SubmitNodeCollector collector, S state, int count) {
		QuadCollection shieldModel = Minecraft.getInstance().getModelManager().getStandaloneModel(SHIELD_MODEL);
		if (shieldModel == null)
			return;

		List<BakedQuad> quads = shieldModel.getAll();
		if (quads.isEmpty())
			return;

		QuadInstance instance = new QuadInstance();

		float age = state.ageInTicks;
		float rotateAngleY = age / -5.0F;
		float rotateAngleX = Mth.sin(age / 5.0F) / 4.0F;
		float rotateAngleZ = Mth.cos(age / 5.0F) / 4.0F;

		for (int c = 0; c < count; c++) {
			stack.pushPose();

			// perform the rotations, accounting for the fact that baked models are corner-based
			// Z gets extra 180 degrees to flip visual upside-down, since scaling y by -1 will cause back-faces to render instead
			stack.mulPose(Axis.ZP.rotationDegrees(180.0F + rotateAngleZ * (180.0F / Mth.PI)));
			stack.mulPose(Axis.YP.rotationDegrees(rotateAngleY * (180.0F / Mth.PI) + (c * (360.0F / count))));
			stack.mulPose(Axis.XP.rotationDegrees(rotateAngleX * (180.0F / Mth.PI)));
			stack.translate(-0.5F, -0.65F, -0.5F);

			// push the shields outwards from the center of rotation
			stack.translate(0.0F, 0.0F, -0.7F);

			collector.submitCustomGeometry(stack, Sheets.translucentItemSheet(), (pose, buffer) -> {
				for (BakedQuad quad : quads) {
					buffer.putBakedQuad(pose, quad, instance);
				}
			});

			stack.popPose();
		}
	}

private void renderLighting(float frame, PoseStack poseStack,Death_Laser_Beam_Entity entity, MultiBufferSource buffer) {
        double x = Mth.lerp(frame, entity.xOld, entity.getX());
        double y = Mth.lerp(frame, entity.yOld, entity.getY());
        double z = Mth.lerp(frame, entity.zOld, entity.getZ());

        double x2 = Mth.lerp(frame, entity.prevCollidePosX, entity.collidePosX);
        double y2 = Mth.lerp(frame, entity.prevCollidePosY, entity.collidePosY);
        double z2 = Mth.lerp(frame, entity.prevCollidePosZ, entity.collidePosZ);



        float f1 = 0.0F;

        if (entity.tickCount > 20) {
            poseStack.pushPose();

            poseStack.translate(-x, -y, -z);
            LightningBoltData.BoltRenderInfo RedboltData = new LightningBoltData.BoltRenderInfo(0.5F, 0.15F, 0.25F, 0.25F, new Vector4f((float) 255 / 255, (float) 26 / 255, (float) 0 / 255, 0.9F), 0.86F);
            LightningBoltData bolt1 = new LightningBoltData(RedboltData, new Vec3(x, y, z), new Vec3(x2, y2, z2), 5)
                    .size(0.1f)
                    .lifespan(1)
                    .spawn(LightningBoltData.SpawnFunction.NO_DELAY)
                    .fade(LightningBoltData.FadeFunction.NONE);

            LightningBoltData.BoltRenderInfo YellowboltData = new LightningBoltData.BoltRenderInfo(0.5F, 0.1F, 0.25F, 0.15F, new Vector4f((float) 249 / 255, (float) 194 / 255, (float) 43 / 255, 0.7F), 0.86F);
            LightningBoltData bolt2 = new LightningBoltData(YellowboltData, new Vec3(x, y, z),  new Vec3(x2, y2, z2), 5)
                    .size(0.07f)
                    .lifespan(1)
                    .spawn(LightningBoltData.SpawnFunction.NO_DELAY)
                    .fade(LightningBoltData.FadeFunction.NONE);

            LightningRender lightningRender = getLightingRender(entity.getUUID());
            if (!Minecraft.getInstance().isPaused()) {
                lightningRender.update(entity, bolt1, frame);
                lightningRender.update(entity, bolt2, frame);
            }
            lightningRender.render(frame, poseStack, buffer);

            poseStack.popPose();

        }
        if (entity.isRemoved() && lightningRenderMap.containsKey(entity.getUUID())) {
            lightningRenderMap.remove(entity.getUUID());
        }
    }

private void renderBeams(
            Ignis_Entity entity,float x, float y, float z, float partialTick, PoseStack poseStack, MultiBufferSource bufferSource, int packedLight) {

        float f = Mth.sqrt(x * x + z * z);
        float f1 = Mth.sqrt(x * x + y * y + z * z);

        if (f1 < 0.01F) return;

        poseStack.pushPose();
        poseStack.translate(0.0F, 0.15F, 0.0F);
        poseStack.mulPose(Axis.YP.rotation((float)(-Math.atan2((double)z, (double)x)) - (float) (Math.PI / 2)));
        poseStack.mulPose(Axis.XP.rotation((float)(-Math.atan2((double)f, (double)y)) - (float) (Math.PI / 2)));

        VertexConsumer vertexconsumer = bufferSource.getBuffer(CMRenderTypes.CMLightning());
        PoseStack.Pose posestack$pose = poseStack.last();
        Matrix4f $$18 = posestack$pose.pose();
        int alpha = (int)(255.0f * 1);

        float beamLength = f1;
        float beamWidth = 0.7F;
        float widthHalf = beamWidth / 2.0F;

        float ax = -widthHalf; float ay = 0.0F; float az = 0.0F;
        float bx =  widthHalf; float by = 0.0F; float bz = 0.0F;
        float cx = -widthHalf; float cy = 0.0F; float cz = beamLength;
        float dx =  widthHalf; float dy = 0.0F; float dz = beamLength;

        int r = entity.getBossPhase() > 0 ? 2: 255;
        int g = entity.getBossPhase() > 0 ? 199: 215;
        int b = entity.getBossPhase() > 0 ? 203: 63;

        vertexconsumer.vertex($$18, ax, ay, az)
                .color(r, g, b, alpha).uv2(packedLight)
                .endVertex();
        vertexconsumer.vertex($$18, bx, by, bz)
                .color(r, g, b, alpha).uv2(packedLight)
                .endVertex();
        vertexconsumer.vertex($$18, dx, dy, dz)
                .color(0, 0, 0, alpha).uv2(packedLight)
                .endVertex();
        vertexconsumer.vertex($$18, cx, cy, cz)
                .color(0, 0, 0, alpha).uv2(packedLight)
                .endVertex();



        poseStack.popPose();
    }

private static void renderShieldingLine(Purpoid purpoid, float partialTicks, PoseStack stack, MultiBufferSource bufferSource, Vec3 mommyPos, int stunTimer) {
		stack.pushPose();
		double interpolatedPurpoidX = Mth.lerp(partialTicks, purpoid.xo, purpoid.getX());
		double interpolatedPurpoidY = Mth.lerp(partialTicks, purpoid.yo, purpoid.getY()) + 0.25F;
		double interpolatedPurpoidZ = Mth.lerp(partialTicks, purpoid.zo, purpoid.getZ());
		stack.translate(0.0F, 0.25F, 0.0F);
		float xDifference = (float) (mommyPos.x - interpolatedPurpoidX);
		float yDifference = (float) (mommyPos.y + 1.0F - interpolatedPurpoidY);
		float zDifference = (float) (mommyPos.z - interpolatedPurpoidZ);
		VertexConsumer vertexconsumer = bufferSource.getBuffer(EERenderTypes.PURPAZOID_SHIELDING_LINE);
		Matrix4f matrix4f = stack.last().pose();
		float width = 0.1F;
		float widthProportionalToDistance = (float) Mth.fastInvSqrt(xDifference * xDifference + zDifference * zDifference) * width / 2.0F;
		float zGap = zDifference * widthProportionalToDistance;
		float xGap = xDifference * widthProportionalToDistance;

		float stunTimerHalfCycles = Math.max(stunTimer - partialTicks, 0.0F) / 20.0F;
		float alpha = 0.1F + 0.4F * (1.0F - 2.0F * Mth.abs(stunTimerHalfCycles - Mth.floor(stunTimerHalfCycles + 0.5F)));

		float baseR = 0.643F;
		float baseG = 0.482F;
		float baseB = 0.918F;
		if (purpoid.hurtTime > 0 || purpoid.deathTime > 0) {
			baseR = baseR * 0.5F + 0.5F;
			baseG *= 0.5F;
			baseB *= 0.5F;
		}

		float waveOffset = Mth.PI * (purpoid.tickCount + partialTicks) / 20.0F;
		for (int i = 0; i <= 48; ++i) {
			addShieldingLineVertexPair(vertexconsumer, matrix4f, alpha, waveOffset, baseR, baseG, baseB, xDifference, yDifference, zDifference, width, width, zGap, xGap, i, false);
		}

		for (int i = 48; i >= 0; --i) {
			addShieldingLineVertexPair(vertexconsumer, matrix4f, alpha, waveOffset, baseR, baseG, baseB, xDifference, yDifference, zDifference, width, 0.0F, zGap, xGap, i, true);
		}

		stack.popPose();
	}

@Override
	public void render(PoseStack stack, MultiBufferSource bufferIn, int packedLightIn, Purpoid purpoid, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch) {
		if (!purpoid.isBaby() || purpoid.getIDOfShieldedMommy() < 0) return;
		PurpoidModel model = this.purpazoidModel;
		model.setupAnim(purpoid, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch);
		PurpoidGelModel gelModel = this.gelModel;
		gelModel.parentToHead(model.head);
		gelModel.setupAnim(purpoid, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch);
		stack.pushPose();
		stack.translate(0.0F, 0.8125F, 0.0F);
		float inAndOut = 0.05F * Mth.abs(Mth.sin(0.15707963267F * ageInTicks));
		float scale = 0.5F + inAndOut;
		stack.scale(scale, scale, scale);
		float alpha = 0.15F + inAndOut;
		VertexConsumer nonEmissiveBuffer = bufferIn.getBuffer(RenderType.entityTranslucent(PurpoidRenderer.getTexture(2)));
		model.renderToBuffer(stack, nonEmissiveBuffer, 240, OverlayTexture.pack(0, 10), 1.0F, 1.0F, 1.0F, alpha);
		gelModel.renderToBuffer(stack, nonEmissiveBuffer, 240, OverlayTexture.pack(0, 10), 1.0F, 1.0F, 1.0F, alpha);
		gelModel.renderToBuffer(stack, bufferIn.getBuffer(RenderType.entityTranslucent(PurpoidEmissiveLayer.TEXTURES[2])), 240, OverlayTexture.pack(0, 10), 1.0F, 1.0F, 1.0F, alpha);
		stack.popPose();
	}
